<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue';
import {createClient} from '@supabase/supabase-js';
import {mountIsland} from './island.js';
const canvas=ref(null),phase=ref(.25),daylight=ref(1),weather=ref('Sunny'),temperature=ref(20),thermal=ref('Comfortable'),swimming=ref(false),wetness=ref(0),weatherSource=ref('Simulated fallback'),wind=ref(0),previewNeeds=ref({health:100,hunger:100,thirst:100,morale:100,energy:100}),journal=ref([]),decision=ref(null),world=ref(null),connected=ref(false),loading=ref(true),tab=ref('journal'),activity=ref({swimming:false,resting:false,freshwaterNearby:false,georgeMoving:false,sitting:false});
let dispose,refresh;let lastSurvivalUpdate=Date.now();
const supabaseUrl=import.meta.env.VITE_SUPABASE_URL;
const supabaseKey=import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const client=supabaseUrl&&supabaseKey?createClient(supabaseUrl,supabaseKey):null;
const journalPreview=[{id:'journal-preview-first',island_day:1,perceived_time:'morning',title:'My first journal entry',entry:'I have begun keeping a journal of my life on this island. There is a camp I can return to, and I need to pay attention to my hunger, thirst and energy. My current priority is explore. I want to learn what this place holds, but I must remember to look after myself.'}];
const displayedJournal=computed(()=>connected.value?journal.value:journalPreview);
const timeLabel=computed(()=>{const h=phase.value*24;return h<5.5?'Night':h<7?'Dawn':h<11?'Morning':h<14?'Midday':h<18?'Afternoon':h<20.5?'Dusk':'Night'});
const clockLabel=computed(()=>{const total=Math.floor(phase.value*1440);return String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0')});
const thought=computed(()=>{const n=connected.value&&world.value?.needs?world.value.needs:previewNeeds.value,a=activity.value;if(connected.value&&world.value?.inventory?.activity==='sitting')return 'I have been walking for half an hour. I am sitting down for five minutes before continuing my journey.';if(connected.value&&decision.value?.thought)return decision.value.thought;if(a.sitting)return 'I have been walking for half an hour. I need to sit down for five minutes, rest my legs, and then I can carry on exploring.';if(a.resting)return 'I have made it back to camp. I need to rest and recover my energy before I set out again.';if((n.energy??100)<30)return 'I am getting tired. I should head back towards my camp and regain my strength.';if((n.thirst??100)<65)return a.freshwaterNearby?'The stream is here. This is fresh water, so I can drink.':'My mouth is getting dry. I need to find the mountain stream; seawater is no good for drinking.';if((n.hunger??100)<35)return 'I am becoming hungry. I need to look for something safe to eat.';if(a.swimming)return 'I am in the water now. I should keep the shore close and avoid exhaustion.';if(thermal.value==='Cold'&&wetness.value>40)return 'I am cold and wet. I should find shelter and warm up.';if(thermal.value==='Hot')return 'The heat is draining me. I should take things slowly and conserve water.';if(a.georgeMoving)return 'I am exploring the island, watching for rocks and trees. I want to learn the landscape and remember the way back to camp.';return 'I am taking in my surroundings and deciding where to explore next. I should keep my camp and freshwater supply in mind.'});
const mood=computed(()=>world.value?.emotions?'Curious':'Curious');
const needs=computed(()=>{const n=connected.value&&world.value?.needs?world.value.needs:previewNeeds.value;return [['Health',n.health??100],['Hunger',n.hunger??100],['Thirst',n.thirst??100],['Morale',n.morale??100],['Energy',n.energy??100]]});
// Survival percentages represent reserves, not an immediate death timer.
// 100 -> 0 thirst in ~48 hours without water at rest; heat/activity accelerate loss.
const SURVIVAL_KEY='george-survival-preview-v2';
let lastDrink=0;
try{const saved=JSON.parse(localStorage.getItem(SURVIVAL_KEY)||'null');if(saved?.needs&&Number.isFinite(saved.at)){previewNeeds.value=saved.needs;lastSurvivalUpdate=Math.max(saved.at,Date.now()-48*3600000)}}catch{}
function advanceSurvival({thermal,swimming,wetness,freshwaterNearby,georgeMoving,resting}){
 const now=Date.now(),minutes=Math.max(0,Math.min((now-lastSurvivalUpdate)/60000,48*60));lastSurvivalUpdate=now;
 const n=previewNeeds.value,hot=thermal==='Hot',cold=thermal==='Cold';
 const thirst=Math.max(0,n.thirst-minutes*(100/(48*60))*(1+(hot?.45:0)+(swimming?.3:0)+(georgeMoving?.15:0)));
 const hunger=Math.max(0,n.hunger-minutes*(100/(14*24*60))*(1+(swimming?.35:0)+(georgeMoving?.15:0)));
 const exposure=cold&&wetness>40?.015:0;
 const damage=minutes*((thirst<15?.045:0)+(hunger<10?.012:0)+exposure);
 const morale=Math.max(0,n.morale-minutes*(.004+(thirst<25?.01:0)));
 const energy=Math.max(0,Math.min(100,(n.energy??100)+minutes*(resting?1.25:-(georgeMoving?.085:.025))));
 const canDrink=freshwaterNearby&&!swimming&&now-lastDrink>120000&&thirst<85;
 const replenished=canDrink?100:thirst;
 if(canDrink)lastDrink=now;
 previewNeeds.value={health:Math.max(0,n.health-damage),hunger,thirst:replenished,morale,energy};
 // Seek only fresh river water. Sea swimming never replenishes thirst.
 window.__georgeNeedsRest=energy<25||(resting&&energy<92);
 window.__georgeNeedsWater=replenished<65&&!window.__georgeNeedsRest;
 try{localStorage.setItem(SURVIVAL_KEY,JSON.stringify({at:now,needs:previewNeeds.value}))}catch{}
}
async function loadData(){if(!client){loading.value=false;return}try{const [w,j,d]=await Promise.all([client.from('world_state').select('day,status,needs,inventory,emotions,stimulation,boredom,novelty_drive,clock_discovered').eq('id',1).maybeSingle(),client.from('george_journal').select('id,island_day,perceived_time,title,entry,created_at').order('island_day',{ascending:false}).order('island_minute',{ascending:false}).limit(20),client.from('george_decisions').select('goal,thought,created_at').order('created_at',{ascending:false}).limit(1).maybeSingle()]);if(w.error||j.error)throw w.error||j.error;world.value=w.data;journal.value=j.data||[];decision.value=d.error?null:d.data;connected.value=true}catch(e){connected.value=false;console.warn('Read-only Supabase data unavailable',e)}finally{loading.value=false}}
onMounted(()=>{dispose=mountIsland(canvas.value,({phase:p,daylight:d,weather:w,temperature:t,thermal:th,swimming:s,wetness:wet,weatherSource:source,wind:windSpeed,freshwaterNearby,georgeMoving,resting,sitting})=>{phase.value=p;daylight.value=d;weather.value=w;temperature.value=t;thermal.value=th;swimming.value=s;wetness.value=wet;weatherSource.value=source;wind.value=windSpeed;activity.value={swimming:s,resting,sitting,freshwaterNearby,georgeMoving};if(!client)advanceSurvival({thermal:th,swimming:s,wetness:wet,freshwaterNearby,georgeMoving,resting})});loadData();refresh=setInterval(loadData,15000)});
onUnmounted(()=>{dispose?.();clearInterval(refresh)});
</script>
<template>
<div class="shell">
<header class="topbar"><div class="brand"><div class="mark">G</div><div><span class="eyebrow">A LIVING ISLAND EXPERIMENT</span><h1>The Island of George</h1></div></div><div class="status"><span class="live-dot"></span> {{connected?'World data connected':'3D prototype'}} <span class="separator">·</span> Day {{world?.day||1}}</div></header>
<main class="layout">
<div class="world-column"><section class="scene-panel"><div class="scene" ref="canvas"></div><div class="scene-overlay"><div class="pill">☀ {{timeLabel}} <span>·</span> {{Math.round(daylight*100)}}% daylight · {{clockLabel}} NZ</div><div class="scene-hint">Drag to orbit · Scroll to zoom · Unlock 🔓 for WASD movement</div></div><div class="scene-footer"><div><span class="eyebrow">GEORGE'S CURRENT WORLD</span><h2>Somewhere on a forgotten island</h2><p>Five biomes to explore. A lifetime of choices ahead.</p></div><span class="tag">PROTOTYPE</span></div></section>
<section class="panel survival-panel"><div class="section-title"><span class="eyebrow">SURVIVAL STATUS · LIVE PREVIEW</span><span class="tag">{{world?.status||'Preview'}}</span></div><h2>George's Health & Needs</h2><div class="meters"><div v-for="[name,value] in needs" :key="name" class="meter"><div class="meter-label"><span>{{name}}</span><strong>{{Math.round(value)}}%</strong></div><div class="track"><div class="fill" :style="{width:value+'%'}"></div></div></div></div><div class="mood">✦ Mood: {{mood}} · Never sleeps, but needs rest</div><div class="mood">☁ {{weather}} · {{temperature}}°C · {{thermal}} · {{swimming?'Swimming':'On land'}} · Wet {{wetness}}%</div><div class="mood">Wind {{wind}} km/h · {{weatherSource}}</div><p class="muted survival-note">When connected, these are George's shared server-side survival values; otherwise browser preview values are shown.</p></section></div>
<aside class="sidebar"><section class="panel thought-panel"><div class="section-title"><span class="eyebrow">GEORGE'S CURRENT THOUGHTS</span><span class="tag">LIVE PREVIEW</span></div><h2>What George is thinking</h2><p class="thought-text">{{thought}}</p><p class="muted thought-disclaimer">When connected, this displays George's server-side decision; otherwise it shows a browser preview.</p></section><section class="panel journal"><div class="tabs"><button :class="{active:tab==='journal'}" @click="tab='journal'">Public journal</button><button :class="{active:tab==='about'}" @click="tab='about'">About the world</button></div><template v-if="tab==='journal'"><p v-if="!connected&&!loading" class="muted" style="padding:12px 18px 0;font-size:12px">Showing George’s first saved entry as a preview. Connect Supabase in Cloudflare to display new journal entries live.</p><div v-if="loading" class="empty">Checking George's journal…</div><div v-else-if="displayedJournal.length===0" class="empty"><div class="book">✎</div><h3>His story hasn't begun yet.</h3><p>When the autonomous AI engine starts writing, George's notes will appear here for everyone to read.</p></div><article v-for="item in displayedJournal" :key="item.id" class="entry"><div class="eyebrow">DAY {{item.island_day}} · {{item.perceived_time}}</div><h3>{{item.title}}</h3><p>{{item.entry}}</p></article></template><div v-else class="about"><p>George will eventually make independent decisions, remember discoveries, react to visitors and document his life here.</p><p>Day and night in this preview follow New Zealand local time. The current 3D character follows a demo route rather than AI decisions.</p><p>All real simulation actions will be validated on the server.</p></div></section></aside>
</main><footer>THE ISLAND OF GEORGE <span>·</span> A survival simulation in development <span>·</span> {{connected?'Read-only Supabase connection active':'Live database not configured in deployment'}}</footer>
</div>
</template>